import{z as n,x as A,o as s,c as d,q as B,j as i,D as o,d as E,s as t,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"GRO / GSO","description":"","frontmatter":{"title":"GRO / GSO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gro-gso.md","filePath":"cs/gro-gso.md","lastUpdated":1791063341000}'),O={name:"cs/gro-gso.md"};function p(S,e,T,c,C,G){const r=A("Mermaid");return s(),d("div",null,[e[2]||(e[2]=B('<h1 id="gro-gso" tabindex="-1">GRO / GSO <a class="header-anchor" href="#gro-gso" aria-label="Permalink to &quot;GRO / GSO&quot;">​</a></h1><div class="epigraph"><p>GRO 在接收路径把同流的小 TCP 段合成一个大 sk_buff；GSO/TSO 在发送路径把大缓冲推迟到网卡或最后一刻再切开。</p><footer>—— 据 Linux GRO/GSO 文档；Corbet 对 TSO 的 LWN 整理</footer></div><p><a href="/cs/napi">上一课</a>已经批量收描述符。若每 1500 字节走一遍 TCP 状态机，PPS 上限太低。缺口是 <strong>聚合与延迟分段</strong>：逻辑上仍是字节流，物理上少跑几次协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TSO：应用 <code>write</code> 64KiB，内核当一包，网卡切成 MSS。无 TSO 则软件 GSO 在出队前切。GRO：相反，NAPI 里把连续 ACK 流合成大 skb，交给 TCP 一次。缺口：必须核对序号、校验、时间戳选项，否则会拼错流；UDP GRO 是后来的亲戚。本课不把 QUIC 卸载写成标准。</p><p><span class="marginnote">LRO 是更早、更粗的硬件聚合，可能破坏语义；GRO 在软件里可验证。GSO 与 UFO（UDP）同类。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：TCP 把大 skb 标 <code>gso_size</code>，qdisc 之后 <code>validate_xmit_skb</code> 决定硬件 TSO 还是软件切开。接收：<code>dev_gro_receive</code> 按流哈希找桶，合并成功则延迟 <code>netif_receive_skb</code> 直到 poll 结束或无法合并。对照 <a href="/cs/skbuff">sk_buff</a>：frags 变长，<code>gso_segs</code> 计数。对照 sendfile：大页天然适合 TSO。</p>',8)),(s(),i(l,null,{default:o(()=>[t(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%A4%A7%20write%22%5D%20--%3E%20GSO%5B%22GSO%2FTSO%20%E5%BB%B6%E8%BF%9F%E5%88%87%22%5D%0A%20%20GSO%20--%3E%20NIC%5B%22%E7%BD%91%E5%8D%A1%E6%88%96%E8%BD%AF%E4%BB%B6%E5%88%86%E6%AE%B5%22%5D%0A%20%20RING%5B%22NAPI%20%E5%B0%8F%E6%AE%B5%22%5D%20--%3E%20GRO%5B%22GRO%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20GRO%20--%3E%20TCP%5B%22TCP%20%E4%B8%80%E6%AC%A1%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"GRO/GSO 把「MTU」从协议 CPU 成本里解开：主机看见大段，线路仍是合法 MTU。这是网络栈与存储大块 I/O 对应的那一课。不要写成量化撮合批处理。校验卸载（checksum offload）常与 TSO 绑定：硬件算 TCP 校验。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},[E("数字实例：MSS 取 1460 字节时，一次 64 KiB 的 "),a("code",null,"write"),E(" 约 65536÷1460≈45 个段。没有 GSO/TSO，TCP 状态机要跑 45 遍；有它只跑 1 遍、网卡切 45 刀——这就是高 PPS 场景省 CPU 的来源。")])],-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：GRO 并没有把线路上的 MTU 变大。网上传输的每个包仍然 ≤1500 字节，合并只发生在主机内存里——出来的大 skb 是「账面合并」，出门前照样按 MTU 切回小包。")],-1)),e[7]||(e[7]=a("p",null,"错误：GRO 拼错会坏流，实现必须保守；虚拟化时要在 vhost 上再做一次。",-1)),(s(),i(l,null,{default:o(()=>[t(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%94%B6%E5%88%B0%E4%B8%80%E4%B8%AA%E5%B0%8F%E6%AE%B5%22%5D%20--%3E%20H%7B%22%E6%8C%89%E6%B5%81%E5%93%88%E5%B8%8C%E6%89%BE%E5%88%B0%E6%A1%B6%EF%BC%9F%22%7D%0A%20%20H%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E5%BC%80%E6%96%B0%E6%A1%B6%E5%B9%B6%E4%B8%8A%E9%80%81%E6%97%A7%E6%95%B0%E6%8D%AE%22%5D%0A%20%20H%20--%20%22%E6%98%AF%22%20--%3E%20C%7B%22%E5%BA%8F%E5%8F%B7%E8%BF%9E%E7%BB%AD%E4%B8%94%E6%A0%A1%E9%AA%8C%E3%80%81%E6%97%B6%E9%97%B4%E6%88%B3%E6%A0%B8%E5%AF%B9%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20M%5B%22%E5%B9%B6%E5%85%A5%E5%A4%A7%20skb%EF%BC%8C%E7%BB%A7%E7%BB%AD%E7%AD%89%E4%B8%8B%E4%B8%80%E6%AE%B5%22%5D%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20S%5B%22%E5%90%88%E5%B9%B6%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%AB%8B%E5%88%BB%E4%B8%8A%E9%80%81%22%5D%0A%20%20M%20--%3E%20T%7B%22poll%20%E7%BB%93%E6%9D%9F%E6%88%96%E6%97%A0%E6%B3%95%E5%86%8D%E5%90%88%E5%B9%B6%EF%BC%9F%22%7D%0A%20%20T%20--%20%22%E6%98%AF%22%20--%3E%20U%5B%22%E4%B8%80%E6%AC%A1%20netif_receive_skb%20%E4%BA%A4%E7%BB%99%20TCP%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=B('<p><span class="marginnote">术语翻译：TSO（TCP Segmentation Offload）就是把「按 MSS 把大块数据切开」这道工序从 CPU 搬到网卡去做；GSO 是它的软件版兜底——网卡不支持时，内核在出队前最后一刻再切。</span></p><p>实现上：GRO 合并失败必须立刻上送，否则延迟 ACK 被自己拖死。TSO 依赖校验卸载，若硬件不做 checksum，软件 GSO 仍要切。隧道要 inner/outer 两套 gso 信息。 读法上只引用<a href="/cs/napi">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>GRO / GSO</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GSO 对隧道封装的全部 inner/outer。不保证所有 virtio 特性位。下一课把 NAPI 之后到套接字之前串成接收路径。</p><p>版本字段会变，课序钉的是机制对象「GRO / GSO」，不是某一主线内核的结构体名。 后课默认：可在收发两侧做段聚合/延迟切。从驱动到 TCP 的上行路径，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GRO 收侧合并；GSO/TSO 发侧延迟分段。</li><li>目的是少跑协议栈，不是改 TCP 语义。</li><li>接收路径是下一课。</li><li>出处：Linux networking；LWN TSO/GRO；Benvenuti。</li></ul>',9))])}const f=n(O,[["render",p]]);export{P as __pageData,f as default};
